  20       if (!session?.user?.id) {
  21         return [];
  22       }
  23 
  24       const response = await fetch('/api/notifications', {
  25         method: 'GET',
  26         headers: {
  27           'Content-Type': 'application/json',
  28         },
  29       });
  30 
  31       if (!response.ok) {
  32         throw new Error('Failed to fetch notifications');
  33       }
  34 
  35       return response.json();
  36     },
  37     enabled: !!session?.user?.id,
  38     refetchInterval: 30000, // Refetch every 30 seconds
  39   });
  40 
  41   return { notifications, isLoading, error };
  42 }
