// Prisma Schema for Arkan PostgreSQL Migration
// This schema is based on the migration plan in docs/migration/

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

// ============================================================================
// NEXTAUTH MODELS
